from datetime import date, timedelta

_ONE_DAY = timedelta(days=1)


def _holiday_set(holidays):
    # Copy into a set so the caller's collection is never touched.
    return frozenset(holidays)


def _is_workday(d, holiday_set):
    return d.weekday() < 5 and d not in holiday_set


def add_workdays(start, days, holidays=()):
    """The date `days` working days from `start`. See TASK.md."""
    if not isinstance(days, int) or isinstance(days, bool):
        raise TypeError("days must be an int, not %s" % type(days).__name__)
    hs = _holiday_set(holidays)

    if days == 0:
        d = start
        while not _is_workday(d, hs):
            d += _ONE_DAY
        return d

    step = _ONE_DAY if days > 0 else -_ONE_DAY
    remaining = abs(days)
    d = start
    while remaining:
        d += step
        if _is_workday(d, hs):
            remaining -= 1
    return d


def count_workdays(first, last, holidays=()):
    """Working days from `first` to `last`, both included. See TASK.md."""
    if first > last:
        return -count_workdays(last, first, holidays)
    hs = _holiday_set(holidays)
    count = 0
    d = first
    while d <= last:
        if _is_workday(d, hs):
            count += 1
        d += _ONE_DAY
    return count
